import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const STATUSES = ['진행전', '진행중', '종료'];
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

const BOOL_FIELDS: [string, string][] = [
  ['commentEnabled', '댓글 사용 여부'],
  ['resultPublic', '결과 공개 여부'],
  ['participantPublic', '참여자 정보 공개 여부'],
  ['messengerNotify', '메신저 알림 사용'],
  ['mobileNotify', '모바일 알림 사용'],
  ['chatroomNotify', '대화방 알림 사용'],
  ['mailNotify', '메일 알림 사용'],
  ['portalNotify', '포털 알림 사용'],
];

@Controller('api/v1')
export class FnSfr03501Controller {
  @Post('/surveys')
  @HttpCode(200)
  async createSurvey(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);

    const title = data['title'];
    if (typeof title !== 'string' || title.trim() === '' || title.length > 200) {
      throw new ApiError(400, 'VALIDATION_FAILED', '설문 제목을 200자 이내로 입력해 주세요.');
    }
    const content = data['content'];
    if (typeof content !== 'string' || content.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '설문 내용을 입력해 주세요.');
    }
    const startDate = data['startDate'];
    if (typeof startDate !== 'string' || !DATE_RE.test(startDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '설문 시작일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const endDate = data['endDate'];
    if (typeof endDate !== 'string' || !DATE_RE.test(endDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '설문 종료일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const status = data['status'];
    if (typeof status !== 'string' || !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '진행상태는 진행전, 진행중, 종료 중 하나여야 합니다.');
    }
    const flags: Record<string, boolean> = {};
    for (const [key, label] of BOOL_FIELDS) {
      const v = data[key];
      if (typeof v !== 'boolean') {
        throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값을 지정해 주세요.');
      }
      flags[key] = v;
    }
    const rawTargets = data['targetEmployeeIds'];
    if (!Array.isArray(rawTargets)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '설문 대상 임직원 목록이 필요합니다.');
    }
    const targetIds: number[] = [];
    for (const t of rawTargets) {
      const n = typeof t === 'string' && t.trim() !== '' ? Number(t) : t;
      if (typeof n !== 'number' || !Number.isInteger(n) || n <= 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '설문 대상 임직원 ID가 올바르지 않습니다.');
      }
      if (!targetIds.includes(n)) {
        targetIds.push(n);
      }
    }

    return transaction(async (db) => {
      const periodRows = await db.query(
        'SELECT (CAST(:endDate AS date) < CAST(:startDate AS date)) AS "invalid"',
        { startDate, endDate },
      );
      if (periodRows[0]['invalid'] === true) {
        throw new ApiError(422, 'INVALID_SURVEY_PERIOD', '종료일은 시작일보다 빠를 수 없습니다.');
      }

      for (const employeeId of targetIds) {
        const found = await db.query(
          'SELECT employee_id AS "employeeId" FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
          { employeeId },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '설문 대상 임직원을 찾을 수 없습니다.');
        }
      }

      const rows = await db.query(
        'INSERT INTO survey (creator_id, title, content, start_date, end_date, status, ' +
          'comment_enabled, result_public, participant_public, ' +
          'messenger_notify, mobile_notify, chatroom_notify, mail_notify, portal_notify, ' +
          'created_at, updated_at) ' +
          'VALUES (CAST(:userId AS bigint), :title, :content, CAST(:startDate AS date), CAST(:endDate AS date), :status, ' +
          ':commentEnabled, :resultPublic, :participantPublic, ' +
          ':messengerNotify, :mobileNotify, :chatroomNotify, :mailNotify, :portalNotify, now(), now()) ' +
          'RETURNING survey_id AS "surveyId", title, content, ' +
          "to_char(start_date, 'YYYY-MM-DD') AS \"startDate\", " +
          "to_char(end_date, 'YYYY-MM-DD') AS \"endDate\", " +
          'status, comment_enabled AS "commentEnabled", result_public AS "resultPublic", ' +
          'participant_public AS "participantPublic", messenger_notify AS "messengerNotify", ' +
          'mobile_notify AS "mobileNotify", chatroom_notify AS "chatroomNotify", ' +
          'mail_notify AS "mailNotify", portal_notify AS "portalNotify"',
        {
          userId: user.id,
          title: title.trim(),
          content,
          startDate,
          endDate,
          status,
          ...flags,
        },
      );
      const survey = rows[0];

      for (const employeeId of targetIds) {
        await db.execute(
          'INSERT INTO survey_target (survey_id, employee_id, created_at, updated_at) ' +
            'VALUES (CAST(:surveyId AS bigint), CAST(:employeeId AS bigint), now(), now())',
          { surveyId: survey['surveyId'], employeeId },
        );
      }

      // 가정: 설정된 알림 채널 발송은 통합 알림 발송(S1, 공통 모듈)이 맡는다.
      return survey;
    });
  }
}

