import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Pairs,
  RefName,
  Select,
  TextInput,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

const NOTIFY_FIELDS: [string, string][] = [
  ['messengerNotify', '메신저 알림 사용'],
  ['mobileNotify', '모바일 알림 사용'],
  ['chatroomNotify', '대화방 알림 사용'],
  ['mailNotify', '메일 알림 사용'],
  ['portalNotify', '포털 알림 사용'],
];

const OPTION_FIELDS: [string, string][] = [
  ['commentEnabled', '댓글 사용 여부'],
  ['resultPublic', '결과 공개 여부'],
  ['participantPublic', '참여자 정보 공개 여부'],
];

const STATUS_OPTIONS: [string, string][] = [
  ['진행전', '진행전'],
  ['진행중', '진행중'],
  ['종료', '종료'],
];

function emptyForm(): Row {
  return {
    title: '',
    content: '',
    startDate: '',
    endDate: '',
    status: '진행전',
    commentEnabled: false,
    resultPublic: false,
    participantPublic: false,
    messengerNotify: false,
    mobileNotify: false,
    chatroomNotify: false,
    mailNotify: false,
    portalNotify: false,
  };
}

export default function FnSfr03501Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [detail, setDetail] = useState<Row | null>(null);
  const [form, setForm] = useState<Row>(emptyForm());
  const [targets, setTargets] = useState<number[]>([]);
  const [picked, setPicked] = useState<number | string>('');

  const set = (key: string, value: unknown) => setForm({ ...form, [key]: value });

  const openForm = () => {
    setForm(emptyForm());
    setTargets([]);
    setPicked('');
    setOpen(true);
  };

  const addTarget = (v: number | string) => {
    setPicked('');
    if (typeof v !== 'number') {
      return;
    }
    if (!targets.includes(v)) {
      setTargets([...targets, v]);
    }
  };

  const submit = async () => {
    if (String(form.title).trim() === '') {
      throw new Error('설문 제목을 입력해 주세요.');
    }
    if (String(form.content).trim() === '') {
      throw new Error('설문 내용을 입력해 주세요.');
    }
    if (!form.startDate || !form.endDate) {
      throw new Error('설문 기간(시작일, 종료일)을 입력해 주세요.');
    }
    if (String(form.endDate) < String(form.startDate)) {
      throw new Error('종료일은 시작일보다 빠를 수 없습니다.');
    }
    const result = await call('POST', '/surveys', role, {
      ...form,
      targetEmployeeIds: targets,
    });
    setRows([{ ...result, targetEmployeeIds: targets }, ...rows]);
    setOpen(false);
    notify('설문조사를 등록했습니다.');
  };

  const notifyNames = (row: Row) =>
    NOTIFY_FIELDS.filter(([key]) => row[key] === true)
      .map(([, label]) => label.replace(' 알림 사용', ''))
      .join(', ') || '없음';

  const ongoing = rows.filter((r) => r.status === '진행중').length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>등록 현황</h2>
        <Tiles
          items={[
            ['이번 등록 건수', rows.length],
            ['진행중', ongoing],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>등록한 설문</h2>
        <Band total={rows.length}>
          <button type="button" onClick={openForm}>
            설문조사 등록
          </button>
        </Band>
        <DataTable
          rows={rows}
          empty="이 화면에서 등록한 설문조사가 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'surveyId', label: '설문조사 ID' },
            { key: 'title', label: '설문 제목' },
            { key: 'startDate', label: '설문 시작일', render: (r) => <DateText value={r.startDate} /> },
            { key: 'endDate', label: '설문 종료일', render: (r) => <DateText value={r.endDate} /> },
            { key: 'status', label: '진행상태', render: (r) => <Badge value={r.status} /> },
          ]}
        />
      </section>

      {open && (
        <Drawer title="설문조사 등록" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="등록">
            <Field label="설문 제목" required wide>
              <TextInput value={form.title} onChange={(v) => set('title', v)} />
            </Field>
            <Field label="설문 내용" required wide>
              <TextInput multiline value={form.content} onChange={(v) => set('content', v)} />
            </Field>
            <Field label="설문 시작일" required>
              <DateInput value={form.startDate} onChange={(v) => set('startDate', v)} />
            </Field>
            <Field label="설문 종료일" required>
              <DateInput value={form.endDate} onChange={(v) => set('endDate', v)} />
            </Field>
            <Field label="진행상태" required>
              <Select value={form.status} onChange={(v) => set('status', v)} options={STATUS_OPTIONS} />
            </Field>
            {OPTION_FIELDS.map(([key, label]) => (
              <Field key={key} label={label}>
                <input
                  type="checkbox"
                  checked={form[key] === true}
                  onChange={(e) => set(key, e.target.checked)}
                />
              </Field>
            ))}
            <Field label="설문 대상 임직원" wide hint="고르면 대상 목록에 추가됩니다.">
              <LookupSelect
                table="employee"
                role={role}
                value={picked}
                onChange={addTarget}
                placeholder="임직원 선택"
              />
              <ul>
                {targets.map((id) => (
                  <li key={id}>
                    <RefName table="employee" role={role} value={id} />{' '}
                    <button type="button" onClick={() => setTargets(targets.filter((t) => t !== id))}>
                      제거
                    </button>
                  </li>
                ))}
              </ul>
            </Field>
            {NOTIFY_FIELDS.map(([key, label]) => (
              <Field key={key} label={label}>
                <input
                  type="checkbox"
                  checked={form[key] === true}
                  onChange={(e) => set(key, e.target.checked)}
                />
              </Field>
            ))}
          </Form>
        </Drawer>
      )}

      {detail && (
        <Drawer title="설문조사 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['설문조사 ID', String(detail.surveyId)],
              ['설문 제목', String(detail.title)],
              ['설문 내용', String(detail.content)],
              ['설문 시작일', <DateText value={detail.startDate} />],
              ['설문 종료일', <DateText value={detail.endDate} />],
              ['진행상태', <Badge value={detail.status} />],
              ['댓글 사용 여부', detail.commentEnabled === true ? '사용' : '미사용'],
              ['결과 공개 여부', detail.resultPublic === true ? '공개' : '비공개'],
              ['참여자 정보 공개 여부', detail.participantPublic === true ? '공개' : '비공개'],
              ['알림 채널', notifyNames(detail)],
              [
                '설문 대상 임직원',
                <span>
                  {((detail.targetEmployeeIds as number[]) || []).map((id) => (
                    <span key={id}>
                      <RefName table="employee" role={role} value={id} />{' '}
                    </span>
                  ))}
                </span>,
              ],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
